-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where step_title_en in ('Prana Pratishtha', 'Udvasanam')
     and (mantra_sanskrit is null
          or (length(mantra_sanskrit) - length(replace(mantra_sanskrit, chr(10), ''))) < 4);
  if n > 0 then raise exception '% of these steps are still short', n; end if;
  -- The verse that traced to no text must be gone from both poojas.
  select count(*) into n from public.pooja_steps
   where mantra_sanskrit like '%प्राणाः प्रतिष्ठन्तु%';
  if n > 0 then raise exception '% steps still carry the unsourced pratishthantu verse', n; end if;
  -- Gender must be right in each: masculine for Ganesha, feminine for the goddess.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Prana Pratishtha' and mantra_sanskrit like '%स्थिरो भव%';
  if n <> 1 then raise exception 'the Ganesha prana pratishtha is not in the masculine'; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Prana Pratishtha'
     and mantra_sanskrit like '%वरदा भव%' and mantra_sanskrit not like '%वरदो भव%';
  if n <> 1 then raise exception 'the Varalakshmi prana pratishtha is not in the feminine'; end if;
  -- The udvasanam verse must be whole, and must end the pooja properly.
  select count(*) into n from public.pooja_steps
   where step_title_en = 'Udvasanam'
     and mantra_sanskrit like '%ते ह नाकं%' and mantra_sanskrit like '%पुनरागमनाय%'
     and mantra_sanskrit like '%शांतिः शांतिः शांतिः%';
  if n <> 2 then raise exception 'expected both udvasanams whole, found %', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
